using Godot;
using System;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PhysicsSettingsOperations
{
    private readonly SurfaceGrowthSettings _surfaceSettings=new();
    private static readonly string[] GrowthAppearance={"color","quality","cross_section","flatten","twist","thickness","tip_thickness","taper","width","feather_tip","feather_asymmetry"};
    public Settings physical_groom(Settings edits){var result=new Settings();foreach(var entry in edits){var values=entry.Value.AsGodotDictionary().Duplicate();foreach(string key in new[]{"color","density","width","thickness","tip_thickness","roll","locked","material"})values.Remove(key);if(values.Count>0)result[entry.Key]=values;}return result;}
    public Variant canonical(Variant value)
    {
        if(value.VariantType==Variant.Type.Dictionary){var source=value.AsGodotDictionary();var result=new Settings();foreach(var key in source.Keys.OrderBy(key=>key.ToString(),StringComparer.Ordinal))result[key.ToString()]=canonical(source[key]);return result;}if(value.VariantType==Variant.Type.Array){var result=new GArray();foreach(var item in value.AsGodotArray())result.Add(canonical(item));return result;}if(value.VariantType!=Variant.Type.Object)return value;var resource=value.AsGodotObject();if(resource is Curve curve){var result=new GArray();for(int i=0;i<curve.PointCount;i++)result.Add(new GArray{curve.GetPointPosition(i),curve.GetPointLeftTangent(i),curve.GetPointRightTangent(i),(int)curve.GetPointLeftMode(i),(int)curve.GetPointRightMode(i)});return result;}if(resource is Mesh mesh){var surfaces=new GArray();for(int i=0;i<mesh.GetSurfaceCount();i++)surfaces.Add((long)GD.Hash(mesh.SurfaceGetArrays(i)));return new GArray{mesh.GetClass().ToString(),mesh.ResourcePath,surfaces};}if(resource is Skin skin){var binds=new GArray();for(int i=0;i<skin.GetBindCount();i++)binds.Add(new GArray{skin.GetBindBone(i),skin.GetBindName(i),skin.GetBindPose(i)});return binds;}if(resource is not Resource saved)return value;
        if(ActorDataOperations.ScriptIs(saved,"res://Workspaces/ModelWorkspace/model_component.gd")){var growth=new GArray();var data=saved.Get("growth").As<Resource>();if(data!=null){var physical=_surfaceSettings.base_settings(data).Duplicate();foreach(string key in GrowthAppearance)physical.Remove(key);var layers=new GArray();foreach(var item in data.Get("groom_layers").AsGodotArray()){var layer=item.AsGodotDictionary();var edits=physical_groom(Get(layer,"changes",new Settings()).AsGodotDictionary());if(edits.Count>0)layers.Add(new GArray{Get(layer,"enabled",true),edits});}var regions=new GArray();foreach(var item in data.Get("regions").AsGodotArray()){var region=item.AsGodotDictionary();var style=Get(region,"style").As<Resource>();if(!ActorDataOperations.ScriptIs(style,"res://Workspaces/ModelWorkspace/growth/growth_style.gd"))continue;var values=style.Get("values").AsGodotDictionary().Duplicate();foreach(string key in GrowthAppearance)values.Remove(key);if(values.Count>0)regions.Add(new GArray{Get(region,"roots",Array.Empty<int>()),Get(region,"faces",Array.Empty<int>()),Get(region,"enabled",true),Get(region,"all",false),values});}growth=new GArray{data.Get("source_id"),data.Get("roots"),data.Get("source_points"),physical,physical_groom(data.Get("groom").AsGodotDictionary()),layers,data.Get("guides"),physical_groom(data.Get("individual").AsGodotDictionary()),regions,data.Get("source_weights"),canonical(data.Get("source_skin"))};}return new GArray{canonical(saved.Get("mesh")),canonical(saved.Get("skin")),canonical(saved.Get("skin_mesh")),saved.Get("transform"),saved.Get("skeleton_id"),saved.Get("bones"),canonical(saved.Get("modifiers")),saved.Get("parameters"),saved.Get("generator"),growth};}if(ActorDataOperations.ScriptIs(saved,"res://Workspaces/ModelWorkspace/model_mesh.gd"))return new GArray{(long)GD.Hash(saved.Get("vertices")),(long)GD.Hash(saved.Get("faces")),saved.Get("smooth")};return new GArray{saved.GetClass().ToString(),saved.ResourcePath};
    }
}
